                        _ = &o;
                        outside = o;
                        continue;
                    }
                }
                if ((inside == null)) {
                    if (input.tryParse(DisplayInside.parse, .{}).asValue()) |i| {
                        _ = &i;
                        inside = i;
                        continue;
                    }
                }
                break;
