            if (((list_item or (inside != null)) or (outside != null))) {
                const final_inside: DisplayInside = ((inside) orelse (DisplayInside.flow));
                const final_outside: DisplayOutside = ((outside) orelse ((switch (final_inside) {
.ruby => .@"inline",
else => .block,
})));
