            }
            const location = input.currentSourceLocation();
            const ident = (switch (input.expectIdent()) {
.result => |v| v,
.err => |e| {
return .{ .err = e };
},
});
            const displayIdentMap = bun.ComptimeStringMap(DisplayPair, .{ .{ "inline-block", DisplayPair{ .outside = .@"inline", .inside = .flow_root, .is_list_item = false } }, .{ "inline-table", DisplayPair{ .outside = .@"inline", .inside = .table, .is_list_item = false } }, .{ "inline-flex", DisplayPair{ .outside = .@"inline", .inside = .{ .flex = css.VendorPrefix{ .none = true } }, .is_list_item = false } }, .{ "-webkit-inline-flex", DisplayPair{ .outside = .@"inline", .inside = .{ .flex = css.VendorPrefix{ .webkit = true } }, .is_list_item = false } }, .{ "-ms-inline-flexbox", DisplayPair{ .outside = .@"inline", .inside = .{ .flex = css.VendorPrefix{ .ms = true } }, .is_list_item = false } }, .{ "-webkit-inline-box", DisplayPair{ .outside = .@"inline", .inside = .{ .box = css.VendorPrefix{ .webkit = true } }, .is_list_item = false } }, .{ "-moz-inline-box", DisplayPair{ .outside = .@"inline", .inside = .{ .box = css.VendorPrefix{ .moz = true } }, .is_list_item = false } }, .{ "inline-grid", DisplayPair{ .outside = .@"inline", .inside = .grid, .is_list_item = false } } });
            if (displayIdentMap.getASCIIICaseInsensitive(ident)) |pair| {
                _ = &pair;
