            }
            return .{ .err = location.newUnexpectedTokenError(.{ .ident = ident }) };
    }

pub fn toCss(self: DisplayPair, dest: *css.Printer) css.PrintErr!void {
            if ((((self.outside == .@"inline") and (self.inside == .flow_root)) and (!self.is_list_item))) {
                return dest.writeStr("inline-block");
            } else {
                if ((((self.outside == .@"inline") and (self.inside == .table)) and (!self.is_list_item))) {
                    return dest.writeStr("inline-table");
